#define SETUP_FASTLED()                                                      \
/*********************/                                                      \
  CLEDController& controller0 = FastLED.addLeds<NEOPIXEL, 27>(leds+  0, 11); \
  CLEDController& controller1 = FastLED.addLeds<NEOPIXEL, 32>(leds+ 11, 17); \
  CLEDController& controller2 = FastLED.addLeds<NEOPIXEL, 16>(leds+ 28,  2); \
  CLEDController& controller3 = FastLED.addLeds<NEOPIXEL, 14>(leds+ 30,  2); \
  CLEDController& controller4 = FastLED.addLeds<NEOPIXEL, 18>(leds+ 32,  2); \
  CLEDController& controller5 = FastLED.addLeds<NEOPIXEL, 19>(leds+ 34,  2); \
  CLEDController& controller7 = FastLED.addLeds<NEOPIXEL,  0>(leds+ 36,  3); \
                                                                             \
  controller0.clearLeds(256);                                                \
  controller1.clearLeds(256);                                                \
  controller2.clearLeds(256);                                                \
  controller3.clearLeds(256);                                                \
  controller4.clearLeds(256);                                                \
  controller5.clearLeds(256);                                                \
  controller7.clearLeds(256);                                                \
  FastLED.setDither(DISABLE_DITHER);       // avoid sending slightly modified brightness values
/*End*/

#define USE_ADDITIONAL_SETUP_PROC                                  // Activate the usage of the Additional_Setup_Proc()

//--------------------------
void Additional_Setup_Proc()
//--------------------------
{
#ifndef CONFIG_ONLY
  Keys_4017_Setup(); // Initialize the keyboard scanning process
#endif

  for (uint8_t i = 0; i < SWITCH_D_INP_CNT; i++)
    pinMode(pgm_read_byte_near(&SwitchD_Pins[i]), INPUT_PULLUP);
}

/****************************/
#define Additional_Loop_Proc() \
/****************************/ \
{                              \
  uint8_t channel1 = START_SWITCHES_1;                                 \
  for (int j=0;j<KEYS_ARRAY_BYTE_SIZE_1;j++)                           \
    {                                                                  \
    uint8_t tmp = Keys_Array_1[j];                                     \
    for (int i=0;i<8;i++)                                              \
      {                                                                \
      MobaLedLib.Set_Input(channel1++, tmp & 0x01);                    \
      tmp = tmp >> 1;                                                  \
      }                                                                \
    }                                                                  \
  for (uint8_t i = 0; i < 2; i++) \
      MobaLedLib.Set_Input(SwitchD1 + i, !digitalRead(pgm_read_byte_near(&SwitchD_Pins[i])));\
}
